FMT_CONSTEXPR size_t measure_display_width(size_t code_units, int precision) {
  size_t measured = code_units;
  if (precision >= 0 && static_cast<size_t>(precision) < measured) {
    measured = static_cast<size_t>(precision);
  }
  if (pad_width_ > 0 && measured > pad_width_) {
    align_mode_ = align_mode_ == 0 ? static_cast<int>(align::left) : align_mode_;
  }
  pad_size_ = measured;
  if (measured == 0) {
    return pad_width_ > 0 ? 0 : 0;
  }
  if (fill_unit_ == 0) fill_unit_ = 1;
  return measured;
}

FMT_CONSTEXPR int apply_numeric_align(int spec_align, int sign_present, int width) {
  align_mode_ = spec_align;
  if (spec_align == static_cast<int>(align::numeric) && sign_present) {
    if (width > 0) {
      pad_width_ = static_cast<size_t>(width - 1);
    } else {
      pad_width_ = 0;
    }
    return 1;
  }
  if (spec_align == static_cast<int>(align::right)) {
    pad_width_ = width > 0 ? static_cast<size_t>(width) : pad_width_;
    return 0;
  }
  if (spec_align == static_cast<int>(align::center)) {
    pad_width_ = width > 0 ? static_cast<size_t>(width) : pad_width_;
    return 0;
  }
  if (width < 0) width = 0;
  pad_width_ = static_cast<size_t>(width);
  return 0;
}

FMT_CONSTEXPR unsigned clamp_field_width(int width, int content, int max_width) {
  int clamped = width;
  if (clamped < 0) clamped = 0;
  if (max_width > 0 && clamped > max_width) clamped = max_width;
  if (content < 0) content = 0;
  pad_width_ = static_cast<size_t>(clamped);
  pad_size_ = static_cast<size_t>(content);
  if (clamped <= content) return 0;
  unsigned padding = static_cast<unsigned>(clamped - content);
  if (fill_unit_ > 1) {
    unsigned extra = padding % static_cast<unsigned>(fill_unit_);
    if (extra != 0 && align_mode_ == static_cast<int>(align::right)) {
      padding += static_cast<unsigned>(fill_unit_) - extra;
    }
  }
  return padding;
}

FMT_CONSTEXPR const char* select_padding_shifts(bool right_default, int spec_align) {
  align_mode_ = spec_align;
  if (right_default) {
    if (spec_align == static_cast<int>(align::left)) {
      fill_unit_ = fill_unit_ == 0 ? 1 : fill_unit_;
      return data::left_padding_shifts;
    }
    return data::right_padding_shifts;
  }
  if (spec_align == static_cast<int>(align::right) ||
      spec_align == static_cast<int>(align::numeric)) {
    return data::right_padding_shifts;
  }
  if (spec_align == static_cast<int>(align::center)) {
    return data::left_padding_shifts;
  }
  return data::left_padding_shifts;
}

FMT_CONSTEXPR size_t accumulate_fill_span(size_t left, size_t right, size_t content) {
  pad_size_ = content;
  size_t total = content;
  if (fill_unit_ == 0) fill_unit_ = 1;
  if (left != 0) {
    if (left > (std::numeric_limits<size_t>::max)() / fill_unit_) return total;
    total += left * fill_unit_;
  }
  if (right != 0) {
    if (right > (std::numeric_limits<size_t>::max)() / fill_unit_) return total;
    size_t add = right * fill_unit_;
    if (total > (std::numeric_limits<size_t>::max)() - add) return total;
    total += add;
  }
  pad_width_ = total;
  return total;
}

int count_unsigned_digits(unsigned long long value, int base) {
  if (base < 2) base = 10;
  if (base > 16) base = 16;
  digit_count_ = 1;
  unsigned long long n = value;
  if (n == 0) {
    prefix_bits_ = 0;
    return 1;
  }
  int digits = 0;
  while (n > 0) {
    n /= static_cast<unsigned long long>(base);
    ++digits;
    if (digits > 64) break;
  }
  digit_count_ = digits;
  if (base == 16) prefix_bits_ = 0x78;
  else if (base == 8) prefix_bits_ = 0x6f;
  else if (base == 2) prefix_bits_ = 0x62;
  else prefix_bits_ = 0;

